INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-mbt-300-black-talon-motorcycle', 1, 'BT-50 Laser Blaster', '3D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast is one melee attack', 'Effectively unlimited on nuclear or Solid Oxide; 180 blasts on electric battery', NULL, 'Standard. One forward-facing laser built into the bike. It can be swapped for another nose gun at that gun''s price plus a 25,000 credit fitting fee. Up to two more weapon systems from the hovercycle range may be added, though NG advises against it: each costs 10% of top speed. On an electric bike a harder-hitting weapon gets half the payload.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 6 machines are in' AS assertion, count(*) AS got, 6 AS want
  FROM vehicles WHERE slug IN ('ng-cm14-alley-cat-motorcycle', 'ng-mbt-300-black-talon-motorcycle', 'ng-em3-electric-citycycle', 'ng-road-hog-motorcycle', 'ng-cm12-streetwolf-motorcycle', 'ng-wm330-wild-boar-motorcycle');
SELECT 'their 29 locations are in' AS assertion, count(*) AS got, 29 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-cm14-alley-cat-motorcycle', 'ng-mbt-300-black-talon-motorcycle', 'ng-em3-electric-citycycle', 'ng-road-hog-motorcycle', 'ng-cm12-streetwolf-motorcycle', 'ng-wm330-wild-boar-motorcycle');
SELECT 'their 1 weapon entries are in' AS assertion, count(*) AS got, 1 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-cm14-alley-cat-motorcycle', 'ng-mbt-300-black-talon-motorcycle', 'ng-em3-electric-citycycle', 'ng-road-hog-motorcycle', 'ng-cm12-streetwolf-motorcycle', 'ng-wm330-wild-boar-motorcycle');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-cm14-alley-cat-motorcycle', 'ng-mbt-300-black-talon-motorcycle', 'ng-em3-electric-citycycle', 'ng-road-hog-motorcycle', 'ng-cm12-streetwolf-motorcycle', 'ng-wm330-wild-boar-motorcycle') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

